    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        
        const endpoint = isLogin ? '/api/auth/login' : '/api/auth/register';
        let payload;
        if (isLogin) {
            payload = { username: formData.username, password: formData.password };
        } else {
            payload = { 
                fullName: formData.fullName, 
                username: formData.username, 
                email: formData.email, 
                password: formData.password,
                role: 'USER' 
            };
        }

        try {
            console.log("Sending data:", payload);
            const res = await axios.post(`http://localhost:8081${endpoint}`, payload);
            
            if (isLogin) {
                login(res.data.user, res.data.token);
                toast.success('🚀 Welcome back!');
                navigate('/dashboard');
            } else {
                toast.success('🎉 Account created! Please login.');
                setIsLogin(true);
                setFormData({ fullName: '', username: '', email: '', password: '' });
            }
        } catch (error) {
            console.error("❌ FULL ERROR OBJECT:", error);
            
            // THIS PART WILL REVEAL THE REAL ERROR MESSAGE
            let errorMessage = "Something went wrong";
            if (error.response) {
                console.log("Server returned error status:", error.response.status);
                console.log("Server returned error data:", error.response.data);
                
                // Spring Boot often sends error messages under 'message', or 'error', or just the string itself
                if (typeof error.response.data === 'string') {
                    errorMessage = error.response.data;
                } else if (error.response.data.message) {
                    errorMessage = error.response.data.message;
                } else if (error.response.data.error) {
                    errorMessage = error.response.data.error;
                }
            } else if (error.request) {
                errorMessage = "Cannot connect to backend on port 8081";
            }
            
            toast.error(`❌ ${errorMessage}`);
        } finally {
            setLoading(false);
        }
    };
